
const mongoose = require("mongoose");

const refundSchema = new mongoose.Schema(
  {
    paymentId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Payment",
      required: true,
      index: true,
    },

    bookingId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Booking",
      required: true,
      index: true,
    },

    // Unique key generated by our application before contacting Razorpay.
    // Retrying the same request must reuse this key.
    requestKey: {
      type: String,
      required: true,
      unique: true,
      trim: true,
      minlength: 8,
      maxlength: 128,
    },

    requestedBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
    },

    amountPaise: {
      type: Number,
      required: true,
      min: 1,
      validate: {
        validator: Number.isSafeInteger,
        message: "Refund amount must be a whole number in paise.",
      },
    },

    currency: {
      type: String,
      enum: ["INR"],
      default: "INR",
      required: true,
    },

    reason: {
      type: String,
      required: true,
      trim: true,
      minlength: 3,
      maxlength: 500,
    },

    status: {
      type: String,
      enum: [
        "REQUESTED",
        "PROCESSING",
        "PROCESSED",
        "FAILED",
        "RECONCILIATION_REQUIRED",
      ],
      default: "REQUESTED",
      required: true,
      index: true,
    },

    gatewayRefundId: {
      type: String,
      default: null,
      trim: true,
    },

    processedAt: {
      type: Date,
      default: null,
    },

    failureReason: {
      type: String,
      default: null,
      maxlength: 1000,
    },

    rawProviderRefs: {
      type: mongoose.Schema.Types.Mixed,
      default: {},
    },

    notes: {
      type: String,
      default: "",
      maxlength: 2000,
    },
  },
  {
    timestamps: true,
  }
);

// A Razorpay refund ID can be attached to only one local refund.
refundSchema.index(
  { gatewayRefundId: 1 },
  {
    unique: true,
    partialFilterExpression: {
      gatewayRefundId: { $type: "string" },
    },
  }
);

refundSchema.index({ paymentId: 1, createdAt: -1 });
refundSchema.index({ bookingId: 1, status: 1 });

module.exports = mongoose.model("Refund", refundSchema);
